(async()=>{if(new URLSearchParams(location.search).get('profile')!=='cave-distribution-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,D=SurvivalData;document.getElementById('welcome').hidden=true;const panel=document.createElement('div');panel.style='position:fixed;inset:0;background:white;color:#234;z-index:10000;overflow:auto;padding:12px';document.body.append(panel);const pre=document.createElement('pre');pre.id='report';panel.append(pre);const report={};const check=(k,v)=>{report[k]=v;pre.textContent=JSON.stringify(report,null,2);if(!v)throw Error(k);};
for(const [index,x,z]of [[0,10000,10000],[1,-50000,50000],[2,96000,-96000]]){q.apply({...D.fresh(),renderQuality:"light",x,z,y:W.ground(x,z),worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);q.world.update(0,q.state);const c=W.caves.find(c=>q.world.caveGroups.some(v=>v.c.id===c.id));check('farCave'+index,!!c);const p=W.cavePoint(c,0,12);q.apply({...D.fresh(),renderQuality:"light",...p,y:W.caveFloor(c,0,12),yaw:Math.atan2(-c.fx,-c.fz),worldTime:360,automaticTime:false,weatherMode:'clear'});q.world.update(0,q.state);await wait(400);const group=q.world.caveGroups.find(v=>v.c.id===c.id&&v.g.userData.surface);group.g.updateWorldMatrix(true,true);const ray=new THREE.Raycaster(new THREE.Vector3(p.x,q.state.y+1,p.z),new THREE.Vector3(0,-1,0));const hit=ray.intersectObject(group.g.userData.surface)[0];check('floor'+index,!!hit&&Math.abs(hit.point.y-q.state.y)<.15);q.renderer.render(q.scene,q.camera);const img=document.createElement('img');img.id='far-cave-'+index;img.style='width:48%';img.src=q.renderer.domElement.toDataURL();panel.append(img);report['loaded'+index]=new Set(q.world.caveGroups.map(v=>v.c.id)).size;}
let dungeon;for(let x=12;x<20&&!dungeon;x++)for(let z=12;z<20&&!dungeon;z++){const c=W.caveDistribution.cell(x,z);if(c?.hasDungeon)dungeon=c;}check('dungeonFound',!!dungeon);q.apply({...D.fresh(),renderQuality:"light",x:dungeon.x,z:dungeon.z,y:dungeon.y});const d=SurvivalDungeons.dungeons.find(v=>v.cave.id===dungeon.id);check('dungeonBuilt',!!d&&q.world.dungeonGroups.some(v=>v.d.id===d.id));const dest=SurvivalDungeons.destination(d,true);q.apply({...D.fresh(),renderQuality:"light",...dest});check('enterDungeon',SurvivalDungeons.at(q.state.x,q.state.z,q.state.y)?.id===d.id);check('lootOnce',!!D.dungeonLoot(q.state,d.index)&&!D.dungeonLoot(q.state,d.index));const back=SurvivalDungeons.destination(d,false);q.apply({...q.snapshot(),...back});check('returnToCave',W.inCave(q.state.x,q.state.z,q.state.y));check('loadedBounded',q.world.caveGroups.length<=32*3);report.done=true;pre.textContent=JSON.stringify(report,null,2);document.title='全世界の洞窟・ダンジョン検証完了';})().catch(e=>{document.getElementById('report').textContent+='\n'+e.stack;document.title='QA error';});
